LCS(A,B) {
	// of size mxn
	mem_table = [[0 for (i=0;i<=len(A);i++)] for (j=0;j<=len(B);j++)]

	for (i=0;i<=len(A);i++) {
		for (j=0;j<=len(B);j++) {
			if (A[i] == B[j]) {
				mem_table[i][j] = 1 + mem_table[i-1][j-1]
			} else {
				mem_table[i][j] = max(mem_table[i-1][j], mem_table[i][j-1])
			}
		}
	}
}
